import{_ as r,a0 as m,w as s,s as l,ao as p,I as e,x as n,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux系統 whoami 命令 – 知曉當前登錄用户 | LCTT x X-CMD","titleTemplate":false,"description":"Linux系統 whoami 命令 – 知曉當前登錄用户 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux系統 whoami 命令 – 知曉當前登錄用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux系統 whoami 命令 – 知曉當前登錄用户 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Linux whoami command – Knowing Who is Logged In","title":"Linux系統 whoami 命令 – 知曉當前登錄用户","tag":"201312","desc":""},"relativePath":"201312/Linux whoami command – Knowing Who is Logged In.md","filePath":"[post].md"}'),h={name:"201312/Linux whoami command – Knowing Who is Logged In.md"};function d(w,o,u,g,x,c){const a=m("Link");return s(),l("div",null,[o[11]||(o[11]=p(`<h1 id="linux系統-whoami-命令-–-知曉當前登錄用户" tabindex="-1">Linux系統 whoami 命令 – 知曉當前登錄用户 <a class="header-anchor" href="#linux系統-whoami-命令-–-知曉當前登錄用户" aria-label="Permalink to “Linux系統 whoami 命令 – 知曉當前登錄用户”">​</a></h1><p>通常，在控制台的命令提示符下你會發現 <strong>用户名已經被顯示出來</strong> 。但有一些 shell 默認情況下不會顯示你的用户名，比如 <strong>csh</strong> 。所以這個命令最應該用在那些不能回顯用户名的 shell 終端上。</p><h3 id="怎麼樣運行-whoami" tabindex="-1">怎麼樣運行 whoami <a class="header-anchor" href="#怎麼樣運行-whoami" aria-label="Permalink to “怎麼樣運行 whoami”">​</a></h3><p>運行這個命令，你只需要輸入 whoami 。下面的例子中我們使用的是 csh shell 終端。</p><pre><code>% whoami
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/csh.png" alt=""></p><h3 id="whoami-的參數選項" tabindex="-1">Whoami 的參數選項 <a class="header-anchor" href="#whoami-的參數選項" aria-label="Permalink to “Whoami 的參數選項”">​</a></h3><p>這個命令僅僅有兩個參數選項： <strong>–help</strong> 和 <strong>–version</strong>。</p><pre><code>% whoamin –help
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/whoami_help.png" alt=""></p><p>下面這選項會輸出和 <strong>man whoami</strong> 命令一樣的信息</p><pre><code>% whoami –version
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/whoami_version.png" alt=""></p><p>不同的是 <strong>–version</strong> 會顯示你係統上 whoami 命令的版本信息</p><h3 id="相似性" tabindex="-1">相似性 <a class="header-anchor" href="#相似性" aria-label="Permalink to “相似性”">​</a></h3><p>whoami 命令和 <strong>id -un</strong> 有相同的輸出。它們都顯示出當前用户的用户名。</p><pre><code>% id -un
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/id-un.png" alt=""></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>whoami 命令也用於當你使用 su 命令（切換用户）時, 它能讓你確認登錄的用户名是否正確。whoami 和 who 命令不相同， who 命令會顯示所有已經登錄的用户名，而 whoami 不是。當你切換用户時，whoami 命令會顯示會話所屬的當前用户，而 who 命令會顯示你切換前的那個源用户。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/whoami_vs_who.png" alt=""></p><hr>`,22)),e("p",null,[o[1]||(o[1]=n("via: ",-1)),i(a,{href:"http://linoxide.com/linux-command/linux-whoami-command/"},{default:t(()=>[...o[0]||(o[0]=[n("http://linoxide.com/linux-command/linux-whoami-command/",-1)])]),_:1})]),e("p",null,[o[4]||(o[4]=n("譯者：",-1)),i(a,{href:"https://github.com/runningwater"},{default:t(()=>[...o[2]||(o[2]=[n("runningwater",-1)])]),_:1}),o[5]||(o[5]=n(" 校對：",-1)),i(a,{href:"https://github.com/carolinewuyan"},{default:t(()=>[...o[3]||(o[3]=[n("Caroline",-1)])]),_:1})]),e("p",null,[o[8]||(o[8]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...o[6]||(o[6]=[n("LCTT",-1)])]),_:1}),o[9]||(o[9]=n(" 原創翻譯，",-1)),i(a,{href:"http://linux.cn/"},{default:t(()=>[...o[7]||(o[7]=[n("Linux中國",-1)])]),_:1}),o[10]||(o[10]=n(" 榮譽推出",-1))])])}const _=r(h,[["render",d]]);export{T as __pageData,_ as default};
